// Validate and prepare input
const body = $input.item.json.body || $input.item.json;
let tickers = body.tickers || ['AAPL', 'MSFT', 'GOOGL'];

if (typeof tickers === 'string') {
  tickers = tickers.split(',').map(t => t.trim());
}

return {
  json: {
    tickers: tickers.map(t => t.toUpperCase()),
    count: body.count || 10,
    timestamp: new Date().toISOString()
  }
};

// Process candles and calculate momentum for each ticker
const response = $input.item.json;
const data = response.data || {};

const results = [];

for (const [ticker, candles] of Object.entries(data)) {
  if (!candles || candles.length === 0) {
    results.push({
      ticker,
      status: 'NO_DATA',
      error: 'No candles available'
    });
    continue;
  }

  // Separate completed and current candles
  const completed = candles.filter(c => c.is_complete);
  const current = candles.find(c => !c.is_complete);

  // Calculate price momentum
  const firstPrice = completed[0]?.open || current?.open || 0;
  const lastPrice = current?.close || completed[completed.length - 1]?.close || 0;
  const priceChangePct = firstPrice > 0 
    ? ((lastPrice - firstPrice) / firstPrice * 100) 
    : 0;

  // Calculate volume metrics
  const volumes = completed.map(c => c.volume).filter(v => v > 0);
  const avgVolume = volumes.length > 0 
    ? volumes.reduce((a, b) => a + b, 0) / volumes.length 
    : 0;
  const lastVolume = current?.volume || completed[completed.length - 1]?.volume || 0;
  const volumeRatio = avgVolume > 0 ? lastVolume / avgVolume : 1;

  // Calculate price range
  const highs = candles.map(c => c.high);
  const lows = candles.map(c => c.low);
  const rangeHigh = Math.max(...highs);
  const rangeLow = Math.min(...lows);
  const rangePct = rangeLow > 0 ? ((rangeHigh - rangeLow) / rangeLow * 100) : 0;

  // Determine momentum signal
  let momentum = 'NEUTRAL';
  let signal = 'HOLD';

  if (priceChangePct > 1.5) {
    momentum = 'STRONG_BULLISH';
    signal = volumeRatio > 1.2 ? 'STRONG_BUY' : 'BUY';
  } else if (priceChangePct > 0.5) {
    momentum = 'BULLISH';
    signal = 'BUY';
  } else if (priceChangePct < -1.5) {
    momentum = 'STRONG_BEARISH';
    signal = 'SELL';
  } else if (priceChangePct < -0.5) {
    momentum = 'BEARISH';
    signal = 'CAUTION';
  }

  results.push({
    ticker,
    current_price: lastPrice.toFixed(2),
    price_change_pct: priceChangePct.toFixed(2),
    momentum,
    signal,
    volume_ratio: volumeRatio.toFixed(2),
    range_high: rangeHigh.toFixed(2),
    range_low: rangeLow.toFixed(2),
    range_pct: rangePct.toFixed(2),
    candle_count: candles.length,
    completed_candles: completed.length,
    has_current: !!current,
    interval: response.interval,
    status: 'OK'
  });
}

// Sort by momentum strength (strongest bullish first)
const order = ['STRONG_BULLISH', 'BULLISH', 'NEUTRAL', 'BEARISH', 'STRONG_BEARISH'];
results.sort((a, b) => order.indexOf(a.momentum) - order.indexOf(b.momentum));

return results.map(r => ({ json: r }));

// Generate summary report
const analyses = $input.all().map(item => item.json);

// Categorize by signal
const categories = {
  STRONG_BUY: analyses.filter(a => a.signal === 'STRONG_BUY'),
  BUY: analyses.filter(a => a.signal === 'BUY'),
  HOLD: analyses.filter(a => a.signal === 'HOLD'),
  CAUTION: analyses.filter(a => a.signal === 'CAUTION'),
  SELL: analyses.filter(a => a.signal === 'SELL')
};

// Build markdown report
let report = `# Real-Time Momentum Report\n`;
report += `**Generated:** ${new Date().toISOString()}\n\n`;

report += `## Summary\n`;
report += `| Signal | Count | Tickers |\n`;
report += `|--------|-------|---------|\n`;
for (const [signal, items] of Object.entries(categories)) {
  if (items.length > 0) {
    report += `| ${signal} | ${items.length} | ${items.map(i => i.ticker).join(', ')} |\n`;
  }
}

report += `\n## Detailed Analysis\n\n`;
report += `| Ticker | Price | Change | Momentum | Signal | Vol Ratio |\n`;
report += `|--------|-------|--------|----------|--------|-----------|\n`;

for (const a of analyses) {
  if (a.status === 'OK') {
    report += `| ${a.ticker} | $${a.current_price} | ${a.price_change_pct}% | ${a.momentum} | ${a.signal} | ${a.volume_ratio}x |\n`;
  }
}

// Top picks
const topBuys = [...categories.STRONG_BUY, ...categories.BUY].slice(0, 3);
if (topBuys.length > 0) {
  report += `\n## Top Picks\n\n`;
  topBuys.forEach((pick, i) => {
    report += `${i + 1}. **${pick.ticker}** - ${pick.momentum} (${pick.price_change_pct}% change, ${pick.volume_ratio}x volume)\n`;
  });
}

return {
  json: {
    report,
    summary: {
      total_analyzed: analyses.length,
      strong_buys: categories.STRONG_BUY.map(a => a.ticker),
      buys: categories.BUY.map(a => a.ticker),
      sells: categories.SELL.map(a => a.ticker)
    },
    analyses,
    timestamp: new Date().toISOString()
  }
};
